## 2. The Caller Component

### Inject IDialogService

```csharp
[Inject] private IDialogService _dialog { get; set; } = default!;
```

### Show the Dialog (Create)

```csharp
private async Task Create()
{
    var model = new MyModel();
    var parameters = new DialogParameters<MyDialogForm>
    {
        { x => x.Model, model }
    };
    var options = new DialogOptions { CloseOnEscapeKey = true, MaxWidth = MaxWidth.Small, FullWidth = true };
    var dialog = await _dialog.ShowAsync<MyDialogForm>("Add Item", parameters, options);
    var result = await dialog.Result;
    if (result is { Canceled: false })
    {
        await _store.AddAsync(model);
        // refresh UI
    }
}
```

### Show the Dialog (Edit)

```csharp
private async Task Edit(MyModel model)
{
    var parameters = new DialogParameters<MyDialogForm>
    {
        { x => x.Model, model }
    };
    var options = new DialogOptions { CloseOnEscapeKey = true, MaxWidth = MaxWidth.Small, FullWidth = true };
    var dialog = await _dialog.ShowAsync<MyDialogForm>("Edit Item", parameters, options);
    var result = await dialog.Result;
    if (result is { Canceled: false })
    {
        await _store.UpdateAsync(model);
        // refresh UI
    }
}
```

**Rules:**
- Always use `DialogParameters<T>` with typed lambda expressions `{ x => x.Property, value }`
- Always await `dialog.Result` to get the `DialogResult`
- Always check `result.Canceled` before acting on the result
- The title is passed as the first argument to `ShowAsync()`, not via `<TitleContent>` in the dialog form

### Real Implementation: OllamaSettings

**Code-Behind** (`Components/Shared/OllamaSettings.razor.cs`):
```csharp
[Inject] private IStore<OllamaConnectionInfo> _store { get; set; } = default!;
[Inject] private IDialogService _dialog { get; set; } = default!;

private async Task Create()
{
    var model = new OllamaConnectionInfo();
    var parameters = new DialogParameters<OllamaConnectionForm>
    {
        { x => x.Model, model }
    };
    var options = new DialogOptions { CloseOnEscapeKey = true, MaxWidth = MaxWidth.Small, FullWidth = true };
    var dialog = await _dialog.ShowAsync<OllamaConnectionForm>("Add Ollama Connection", parameters, options);
    var result = await dialog.Result;
    if (result is { Canceled: false })
    {
        await _store.AddAsync(model);
        _models = await _store.FindManyAsync(x => true, ...);
        this.StateHasChanged();
    }
}

private async Task Edit(OllamaConnectionInfo model)
{
    var parameters = new DialogParameters<OllamaConnectionForm>
    {
        { x => x.Model, model }
    };
    var options = new DialogOptions { CloseOnEscapeKey = true, MaxWidth = MaxWidth.Small, FullWidth = true };
    var dialog = await _dialog.ShowAsync<OllamaConnectionForm>("Edit Ollama Connection", parameters, options);
    var result = await dialog.Result;
    if (result is { Canceled: false })
    {
        await _store.UpdateAsync(model);
        _models = await _store.FindManyAsync(x => true, ...);
        this.StateHasChanged();
    }
}
```

### Real Implementation: Servers (Extensa)

**Code-Behind** (`Components/Shared/Servers.razor.cs`):
```csharp
[Inject] private IPluginServerService _service { get; set; } = default!;
[Inject] private IDialogService _dialog { get; set; } = default!;

private async Task Add()
{
    var model = new PluginServer();
    var parameters = new DialogParameters<ServerForm> { { x => x.Model, model } };
    var options = new DialogOptions { CloseButton = true, MaxWidth = MaxWidth.Small };
    var dialog = await _dialog.ShowAsync<ServerForm>("Add Extension Server", parameters, options);
    var result = await dialog.Result;
    if (result != null && !result.Canceled)
    {
        await _service.AddServerAsync(model);
        _models = await _service.GetAllServers();
        this.StateHasChanged();
    }
}

private async Task Edit(PluginServer model)
{
    var parameters = new DialogParameters<ServerForm> { { x => x.Model, model } };
    var options = new DialogOptions { CloseButton = true, MaxWidth = MaxWidth.Small };
    var dialog = await _dialog.ShowAsync<ServerForm>("Edit Extension Server", parameters, options);
    var result = await dialog.Result;
    if (result != null && !result.Canceled)
    {
        await _service.UpdateServerAsync(model);
        _models = await _service.GetAllServers();
        this.StateHasChanged();
    }
}
```

**Note:** The `Servers` component uses `result != null && !result.Canceled` while `OllamaSettings` and `OpenAISettings` use `result is { Canceled: false }`. Both are acceptable; the property pattern is preferred for conciseness.

